theorem dValue_ne_zero {F : OrthogonalFrame (tau (residualSourceLift s))}
    {i : GeneratorIndex} (hgcd : tripleGcd (dValue F i) = 1) :
    dValue F i ≠ ⟨0, 0, 0⟩

theorem mem_validIndices_of_block (F : OrthogonalFrame (tau (residualSourceLift s)))
    {h : ℤ} (hh1 : 1 ≤ h) (hh2 : h ≤ hMax n) {i : GeneratorIndex}
    (hi : i ∈ blockIndexList n F h) (hr : Retained s F i) : i ∈ validIndices s F

theorem oneBlock_advance (F : OrthogonalFrame (tau (residualSourceLift s)))
    {st : GenState} (hst : OneBlock s F st) {r : IncidentRecord} {st' : GenState}
    (h : advance s F st = some (r, st')) : OneBlock s F st'

theorem signActA_neg_sign {n : ℤ} (hnpos : 0 < n) {σ : ℤ}
    (hσ : σ = 1 ∨ σ = -1) (y : AResidual n) :
    signActA hnpos (-σ) y = negAResidual (signActA hnpos σ y)

theorem signedPartner_signActA {n : ℤ} (hnpos : 0 < n) {σ : ℤ}
    (hσ : σ = 1 ∨ σ = -1) (s : BResidual n) (t : AResidual n) :
    signedPartner hnpos s (signActA hnpos σ t) = signedPartner hnpos s t

theorem liftOrbitEquiv_neg_representative (M : I.Orbit ≃ J.Orbit)
    (sign : ∀ _q : I.Orbit, Bool ≃ Bool) (q : I.Orbit) :
    I.liftOrbitEquiv J M sign (I.neg (I.representative q)) =
      if sign q true then J.neg (J.representative (M q))
      else J.representative (M q)

theorem orthogonalFrameExec_span_unique (hp : tripleGCD p = 1) {r : Triple}
    (hr : dot p r = 0) :
    ∃! ab : ℤ × ℤ, r = span2 ab.1 ab.2 (frameE₁ p) (frameE₂ p)

theorem recordOf_sign_eq_etaPoint (hnpos : 0 < n)
    (F : OrthogonalFrame (tau (residualSourceLift s))) {i : GeneratorIndex}
    (hret : Retained s F i) {o : (aResidualInvolution n hnpos).Orbit}
    (hrt : (recordOf s F i).target = orbitTargetLift hnpos o) :
    (recordOf s F i).sign =
      etaPoint s (canonicalAResidualRepresentative hnpos o)

theorem canonical_of_mem_sourceRosterExec {n : ℤ} {x : BResidual n}
    (hx : x ∈ sourceRosterExec n) :
    canonicalBResidualRepresentative ((bResidualInvolution n).orbit x) = x

theorem mem_sourceRosterExec_of_canonical {n : ℤ} {x : BResidual n}
    (hx : canonicalBResidualRepresentative ((bResidualInvolution n).orbit x) = x) :
    x ∈ sourceRosterExec n

theorem advance_nextBlock_pos (F : OrthogonalFrame (tau (residualSourceLift s)))
    {st : GenState} (hst : 1 ≤ st.nextBlock) {r : IncidentRecord} {st' : GenState}
    (h : advance s F st = some (r, st')) : 1 ≤ st'.nextBlock

theorem fibre_direct_41_set :
