      {sourceDirect41a, sourceDirect41b}

theorem fibre_residual_41_set :
    {p : BRep 41 | paperTunnellMapExec pos41 squarefree41 t1 p = targetResidual41} =
      {sourceResidual41a, sourceResidual41b}

theorem tunnellMapTotal41_fibre_direct_set :
    {p : BRep 41 | tunnellMapTotal41 p = targetDirect41} =
      {sourceDirect41a, sourceDirect41b}

theorem tunnellMapTotal41_fibre_residual_set :
    {p : BRep 41 | tunnellMapTotal41 p = targetResidual41} =
      {sourceResidual41a, sourceResidual41b}

theorem qForm_dValue_of_rawIndex (F : OrthogonalFrame p) {i : GeneratorIndex}
    (hi : i ∈ rawIndices n F) (hparity : InTauLattice (rValue F i)) :
    qForm (dValue F i) = i.A

theorem run_eq_of_reaches (frames : FrameFamily n) {E E' : DARun n}
    (hreach : Reaches frames E E') (hstop : step frames E' = none) :
    run frames E = E'

theorem primitiveDirection_eq_self_of_content_one_of_oriented {v : Triple}
    (hcontent : tripleContent v = 1) (horiented : FirstNonzeroPositive v) :
    primitiveDirection v = v

theorem stepTrace_step (hn : 0 ≤ n) (frames : FrameFamily n) {E : DARun n}
    (hgen : GenStarted E) :
    (stepTrace frames E).map Prod.snd = step frames E

theorem stepTrace_accept_iff_free (frames : FrameFamily n) {E : DARun n}
    {ev : DAEvent n} {E' : DARun n} (h : stepTrace frames E = some (ev, E')) :
    ev.outcome = DAOutcome.accept ↔ E.held ev.target = none

@[simp] theorem directionKey_primitiveDirection {v : Triple}
    (hv : v ≠ ⟨0, 0, 0⟩) :
    directionKey (primitiveDirection v) = directionKey v

@[simp] theorem representativeEdgeKey_neg_source {n : ℤ}
    (s : BResidual n) (t : AResidual n) :
    representativeEdgeKey (negBResidual s) t = representativeEdgeKey s t

@[simp] theorem representativeEdgeKey_neg_target {n : ℤ}
    (s : BResidual n) (t : AResidual n) :
    representativeEdgeKey s (negAResidual t) = representativeEdgeKey s t

theorem representativeEdgeKey_source_orbit_injective {n : ℤ}
    (hnpos : 0 < n) (s : BResidual n) {t₁ t₂ : AResidual n}
    (hkey : representativeEdgeKey s t₁ = representativeEdgeKey s t₂) :
    (aResidualInvolution n hnpos).orbit t₁ =
      (aResidualInvolution n hnpos).orbit t₂

theorem representativeEdgeKey_target_orbit_injective {n : ℤ}
    (t : AResidual n) {s₁ s₂ : BResidual n}
    (hkey : representativeEdgeKey s₁ t = representativeEdgeKey s₂ t) :
    (bResidualInvolution n).orbit s₁ = (bResidualInvolution n).orbit s₂

theorem primitiveKey_eq_directionKey {v : Triple}
    (hcontent : tripleGcd v = 1) (horiented : FirstNonzeroPositive v) :
    primitiveKey v = directionKey v

theorem oneBlockAll_step (frames : FrameFamily n) {E E' : DARun n}
    (hE : OneBlockAll frames E) (h : step frames E = some E') :
    OneBlockAll frames E'

theorem liftOrbitEquiv_representative (M : I.Orbit ≃ J.Orbit)
    (sign : ∀ _q : I.Orbit, Bool ≃ Bool) (q : I.Orbit) :
    I.liftOrbitEquiv J M sign (I.representative q) =
      if sign q false then J.neg (J.representative (M q))
      else J.representative (M q)

theorem orthogonalFrame_exists_of_squarefree_norm {p : Triple} {n : ℤ}
    (hn : Squarefree n) (hnorm : dot p p = n) :
    Nonempty (OrthogonalFrame p)

theorem reconstructedTarget_same_norm {E d : Triple} {A q : ℤ}
    (hA : qForm d = A) (hB : qBilinear E d = q * A) :
    qForm (reconstructedTarget E q d) = qForm E

theorem generatorWitness_reconstructs_target {n : ℤ} {s : BResidual n}
    {t : AResidual n} {R : PreferredMidpointRecord s t}
    (W : GeneratorWitness s t R) :
    residualTargetLift R.target =
      reconstructedTarget (residualSourceLift s) W.q R.direction
